    @Override
    public void sendPhone(String phone) {
        // 1. 生成随机6位验证码
        String code = String.valueOf((int)((Math.random()*9 + 1)*100000));
        // 2. 存储到Redis
        String key = RedisConstant.PHONE_CODE_KEY + phone;
        RedisUtils.set(key, code, RedisConstant.PHONE_CODE_EXPIRE, TimeUnit.MINUTES);

        // 3. 调用阿里云短信接口发送
        try {
            ClientOverrideConfiguration config = new ClientOverrideConfiguration.Builder()
                    .setCredentialsProvider(new StaticCredentialProvider(new Credential(aliAccessKeyId, aliAccessKeySecret)))
                    .build();
            AsyncClient client = new AsyncClient(config);
            SendSmsRequest request = new SendSmsRequest();
            request.setPhoneNumbers(phone);
            request.setSignName("TalkTime"); // 假设签名名为TalkTime
            request.setTemplateCode("SMS_TEMPLATE_CODE"); // 假设模板代码
            request.setTemplateParam("[" + code + "]");
            client.sendSms(request);
        } catch (Exception e) {
            throw new TalkTimeException("短信发送失败");
        }
    }

    /**
     * 注册
     *
     * @param paramDTO 参数对象
     * @param request 请求
     * @author qingmeng
     * @createTime: 2023/11/13 07:51:11
     */
    @Override
    @Transactional
    public void register(RegisterDTO paramDTO, HttpServletRequest request) {
        // 1. 校验手机验证码
        String key = RedisConstant.PHONE_CODE_KEY + paramDTO.getPhone();
        String code = RedisUtils.get(key);
        if (StrUtil.isBlank(code) || !code.equals(paramDTO.getPhoneCode())) {
            throw new TalkTimeException("手机验证码错误或已过期");
        }

        // 2. 检查账号是否已存在
        SysUser existingUser = sysUserDao.getUserByAccount(paramDTO.getAccount());
        if (existingUser != null) {
            throw new TalkTimeException("该账号已被注册");
        }

        // 3. 构建用户对象并保存
        SysUser sysUser = LoginAboutAdapt.buildRegister(paramDTO);
        sysUserDao.insert(sysUser);

        // 4. 初始化隐私设置
        SysUserPrivacySetting privacySetting = UserSettingAdapt.buildDefalutSysUserPrivacySetting(sysUser.getId());
        sysUserPrivacySettingDao.insert(privacySetting);

        // 5. 发布注册事件（用于异步处理如发送欢迎消息等）
        applicationEventPublisher.publishEvent(new SysUserRegisterEvent(this, sysUser, request));
    }

