```java
    /**
     * Imports claims from the GriefPrevention database.
     *
     * @return The total number of claims imported.
     */
    public int importClaims() {
        final int totalClaims = getTotalClaims();
        final int totalPages = (int) Math.ceil((double) totalClaims / CLAIMS_PER_PAGE);
        final AtomicInteger amount = new AtomicInteger(0);
        final Set<ClaimWorld> claimWorlds = Sets.newHashSet();
        final Map<Integer, Claim> allClaims = Maps.newHashMap();
        final List<GriefPreventionUser> users = Lists.newArrayList();

        log(pool, Level.INFO, "Importing %s claims across %s pages...".formatted(totalClaims, totalPages));

        for (int page = 1; page <= totalPages; page++) {
            final List<GriefPreventionClaim> pageClaims = getClaimPage(page).join();

            pageClaims.forEach(gpc -> {
                // Convert GP coordinates to HuskClaims Region
                final Region region = Region.from(
                        Region.Point.at(gpc.lesserCorner.x, gpc.lesserCorner.z),
                        Region.Point.at(gpc.greaterCorner.x, gpc.greaterCorner.z)
                );

                // Create the HuskClaims Claim instance
                final Claim hcc = Claim.createAdminClaim(region, plugin);
                allClaims.put(gpc.id, hcc);

                // Map GP trust levels to HuskClaims TrustLevels
                // Note: This assumes a mapping exists or uses default trust levels
                mapTrustees(gpc, hcc);

                hcc.setInheritParent(!gpc.inheritNothing);

                // Get the claim world
                final Optional<ClaimWorld> optionalWorld = plugin.getClaimWorld(gpc.world);
                if (optionalWorld.isEmpty()) {
                    plugin.log(Level.WARNING, "Skipped claim at %s on missing world %s".formatted(gpc.lesserCorner, gpc.world));
                    return;
                }
                final ClaimWorld claimWorld = optionalWorld.get();

                // Add the claim world to the list of worlds, then cache the claim owner/trustees
                claimWorlds.add(claimWorld);
                hcc.getOwner().flatMap(owner -> users.stream().filter(gpu -> gpu.uuid.equals(owner)).findFirst())
                        .ifPresent(user -> claimWorld.cacheUser(user.toUser()));
                hcc.getTrustedUsers().keySet().forEach(u -> users.stream().filter(gpu -> gpu.uuid.equals(u))
                        .findFirst().ifPresent(user -> claimWorld.cacheUser(user.toUser())));

                // Add the claim to either its parent or the claim world
                if (gpc.isChildClaim()) {
                    allClaims.entrySet().stream()
                            .filter(entry -> entry.getValue().id == gpc.parentId)
                            .map(Map.Entry::getKey).findFirst()
                            .ifPresent(parent -> {
                                parent.getOwner().ifPresent(hcc::setOwner);
                                parent.getChildren().add(hcc);
                            });
                } else {
                    claimWorld.getClaims().add(hcc);
                }

                if (amount.incrementAndGet() % CLAIMS_PER_PAGE == 0) {
                    log(executor, Level.INFO, "Saved %s claims...".formatted(amount.get()));
                }
            });
        }

        // Save claim worlds
        plugin.clearAllMapMarkers();
        log(executor, Level.INFO, "Saving %s claim worlds...".formatted(claimWorlds.size()));
        final List<CompletableFuture<Void>> claimWorldFutures = Lists.newArrayList();
        claimWorlds.forEach(claimWorld -> claimWorldFutures.add(
                CompletableFuture.runAsync(() -> plugin.getDatabase().updateClaimWorld(claimWorld), pool)
        ));
        CompletableFuture.allOf(claimWorldFutures.toArray(CompletableFuture[]::new)).join();
        plugin.markAllClaims();
        return amount.get();
    }

    private void mapTrustees(GriefPreventionClaim gpc, Claim hcc) {
        // Logic to map GP's specific roles (builders, containers, etc.) to HuskClaims TrustLevels
        // This is a simplified mapping example
        gpc.managers.forEach(name -> {
            plugin.getTrustLevel("manager").ifPresent(level -> hcc.setUserTrustLevel(UUID.randomUUID(), level)); 
            // In a real scenario, you would resolve the name to a UUID first
        });
    }

    private void log(Object executor, Level level, String message) {
        plugin.log(level, message);
    }

    // Helper classes to represent GP Database rows
    private record GriefPreventionPoint(int x, int z) {
        static GriefPreventionPoint parse(String s) {
            String[] parts = s.split(",");
            return new GriefPreventionPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
        }
    }

    private record GriefPreventionClaim(
            int id, String owner, String world, GriefPreventionPoint lesserCorner, 
            GriefPreventionPoint greaterCorner, List<String> builders, List<String> containers, 
            List<String> accessors, List<String> managers, boolean inheritNothing, int parentId) {

        boolean isChildClaim() { return parentId != -1; }
