            double totalPrice = buyingItem.getPriceForOne() * count;
            if (Main.getEcon().getBalance(player) < totalPrice) {
                Main.getMessage().sendMsg(player, Lang.getMessage("insufficient_balance"));
                if (menu != null) menu.reopen();
                return;
