                Main.getMessage().sendMsg(player, buyingItem.replace(Lang.getMessage("successful_purchase")));

                // Notify seller via network packet if applicable
                Main.getStorage().addSqlToQueue("INSERT INTO logs (time, type, owner, server, uuid) VALUES (%s, 'BUY_ITEM', '%s', '%s', '%s')", 
                        System.currentTimeMillis(), buyingItem.getSellerUuid(), Main.getServerId(), buyingItem.getUniqueName().getKey());
            } else {
                Main.getMessage().sendMsg(player, String.valueOf(event.getReason()));
                if (menu != null) menu.reopen();
            }
        } else {
            if (menu != null) menu.reopen();
        }
