        toast.addListener(new TableShowHideListener() {
            @Override
            public void tableShown(Event event) {
                if (currentToast != null) {
                    currentToast.hide();
                }
            }

            @Override
            public void tableHidden(Event event) {
                if (currentToast == toast) {
                    currentToast = null;
                    if (toastQueue.size > 0) {
                        var nextToast = toastQueue.removeIndex(0);
                        nextToast.show(foregroundStage);
                    }
                }
            }
        });

        currentToast = toast;
        toast.show(foregroundStage);
    }

    public static void queueToast(String text) {
        var transitionTime = currentToast != null ? .2f : .5f;
        var showTime = currentToast != null ? .5f : .7f;
        var toast = new Toast(skin.get("toast", WindowStyle.class), transitionTime, showTime);

        var label = new Label(text, skin);
        toast.add(label);

        toast.addListener(new TableShowHideListener() {
            @Override
            public void tableShown(Event event) {
                if (currentToast != null && currentToast != toast) {
                    currentToast.hide();
                }
            }

            @Override
            public void tableHidden(Event event) {
                if (currentToast == toast) {
                    currentToast = null;
                    if (toastQueue.size > 0) {
                        var nextToast = toastQueue.removeIndex(0);
                        nextToast.show(foregroundStage);
                    }
                }
            }
        });

        toastQueue.add(toast);
        if (currentToast == null) {
            showToast(text);
        }
    }
}
```

