    public BlockPlacer(LocalPlayerPositionService localPlayerPositionService, MotionUpdateService motionUpdateService, AntiCheat antiCheat, Minecraft minecraft, InventoryService inventoryService) {
        super(PRIORITY);
        this.localPlayerPositionService = localPlayerPositionService;
        this.motionUpdateService = motionUpdateService;
        this.antiCheat = antiCheat;
        this.minecraft = minecraft;

        listen(new SafeListener<PreMotionPlayerUpdateEvent>(minecraft, Integer.MAX_VALUE) {
            @Override
            public void onEvent(PreMotionPlayerUpdateEvent event, LocalPlayer player, ClientLevel level, MultiPlayerGameMode gameMode) {
                if (minecraft.isSameThread()) {
                    inTick = true;
                    actions.clear();
                    completed = false;
                    attacked = false;
                    crystal = null;

                    // Process block placing modules
                    while (!modules.isEmpty()) {
                        PlacesBlocks module = modules.poll();
                        if (module != null) {
                            module.place(this, player, level, gameMode);
                        }
                    }

                    executeActions(player, level, gameMode, inventoryService);
                    inTick = false;
                }
            }
        });

        listen(new SafeListener<PostMotionPlayerUpdateEvent>(minecraft, Integer.MIN_VALUE) {
            @Override
            public void onEvent(PostMotionPlayerUpdateEvent event, LocalPlayer player, ClientLevel level, MultiPlayerGameMode gameMode) {
                // Post-tick cleanup if necessary
            }
        });
    }

    private void executeActions(LocalPlayer player, ClientLevel level, MultiPlayerGameMode gameMode, InventoryService inventoryService) {
        if (actions.isEmpty()) return;

        inventoryService.use(context -> {
            for (Action action : actions) {
                if (completed) break;

                // Handle rotations
                if (antiCheat.getBlockRotations().getValue()) {
                    float[] rots = RotationUtil.getRotations(player, level, action.getPos(), action.getDirection());
                    motionUpdateService.setRotations(rots[0], rots[1]);
                }

                // Switch to required item
                InventoryContext.SwitchResult switchResult = context.switchTo(action.getItem(), PREFER_MAINHAND | SET_CARRIED_ITEM | SWITCH_BACK);
                if (switchResult == null) continue;

                // Perform placement
                BlockHitResult hitResult = RaytraceUtil.raytraceToPlaceTarget(player, level, action.getPos(), (pos, dir) -> {
                    return antiCheat.getStrictDirectionCheck().strictDirectionCheck(pos, dir, level, player);
                }, antiCheat.getOpposite().getValue());

                if (hitResult != null) {
                    gameMode.handleUseItemOn(new ServerboundUseItemOnPacket(
                            hitResult.getBlockPos(), 
                            hitResult.getDirection(), 
                            InteractionHand.MAIN_HAND
                    ));

                    if (action.isCrystal()) {
                        attacked = true;
                        completed = true;
                    }
                }
            }
        });
    }

    @Data
    @AllArgsConstructor
    public static class Action {
        private final BlockPos pos;
        private final Direction direction;
        private final Item item;
        private final boolean crystal;

        public boolean isCrystal() {
            return crystal;
        }
