	public GetAllRoomsResponse searchRooms(String keyword, RoomType roomType, Long roomId) {
		List<Room> rooms = (keyword == null || keyword.isBlank()) 
			? roomSearchRepository.findAllWithNoOffset(roomType, roomId)
			: roomSearchRepository.searchWithKeyword(keyword, roomType, roomId);

		boolean hasNext = rooms.size() > ROOM_FIXED_SEARCH_SIZE;
		if (hasNext) {
			rooms = rooms.subList(0, ROOM_FIXED_SEARCH_SIZE);
		}

		List<GetAllRoomResponse> getAllRoomResponses = rooms.stream()
			.map(room -> {
				List<Routine> routines = routineRepository.findAllByRoomId(room.getId());
				List<RoutineResponse> routineResponses = RoutineMapper.toRoutineResponses(routines);
				boolean isPassword = !StringUtils.isEmpty(room.getPassword());
				return RoomMapper.toSearchAllRoomResponse(room, routineResponses, isPassword);
			})
			.toList();

		return RoomMapper.toSearchAllRoomsResponse(hasNext, getAllRoomResponses);
	}

	public UnJoinedRoomDetailsResponse getUnJoinedRoomDetails(Long roomId) {
		Room room = roomRepository.findById(roomId)
			.orElseThrow(() -> new NotFoundException(ROOM_NOT_FOUND));

		List<Routine> routines = routineRepository.findAllByRoomId(roomId);
		List<RoutineResponse> routineResponses = RoutineMapper.toRoutineResponses(routines);

		List<Participant> participants = participantSearchRepository.findAllByRoomId(roomId);
		List<Long> memberIds = participants.stream()
			.map(Participant::getMemberId)
			.toList();

		List<Member> members = memberService.getRoomMembers(memberIds);
		List<UnJoinedRoomCertificateRankResponse> rankResponses = new ArrayList<>();

		for (int i = 0; i < members.size(); i++) {
			Member member = members.get(i);
			Inventory inventory = inventorySearchRepository.findDefault(member.getId(), 
				ItemType.valueOf(room.getRoomType().name()));

			rankResponses.add(RoomMapper.toUnJoinedRoomCertificateRankResponse(member, i + 1, inventory));
		}

		return RoomMapper.toUnJoinedRoomDetails(room, routineResponses, rankResponses);
	}

	private List<RoutineResponse> getRoutineResponses(Long roomId) {
		List<Routine> routines = routineRepository.findAllByRoomId(roomId);
		return RoutineMapper.toRoutineResponses(routines);
	}

	private List<LocalDate> getCertifiedDatesBeforeWeek(Long roomId) {
		List<DailyRoomCertification> certifications = certificationsSearchRepository.findDailyRoomCertifications(roomId, clockHolder.date());
		return certifications.stream()
			.map(DailyRoomCertification::getCertifiedAt)
			.toList();
	}

	private double calculateCompletePercentage(int certifiedCount, Room room, LocalDate date) {
		List<Participant> participants = participantSearchRepository.findAllByRoomId(room.getId());
		if (participants.isEmpty()) return 0.0;
		return (double) certifiedCount / participants.size() * 100;
	}

	private int calculateContributionPoint(Long memberId, List<Participant> participants, LocalDate date) {
		return participants.stream()
			.filter(p -> p.getMemberId().equals(memberId))
			.findFirst()
			.map(Participant::getCertifyCount)
			.orElse(0);
	}

	private List<TodayCertificateRankResponse> getTodayCertificateRankResponses(Long memberId, Long roomId, 
		List<DailyMemberCertification> dailyMemberCertifications, LocalDate date, RoomType roomType) {

		List<TodayCertificateRankResponse> responses = new ArrayList<>();
		for (int i = 0; i < dailyMemberCertifications.size(); i++) {
			DailyMemberCertification dmc = dailyMemberCertifications.get(i);
			Member member = memberService.findMember(dmc.getMemberId());

			List<Certification> certifications = certificationsSearchRepository.findCertifications(roomId, date)
				.stream()
				.filter(c -> c.getMemberId().equals(member.getId()))
				.toList();

			List<CertificationImageResponse> imageResponses = new ArrayList<>();
			for (Routine routine : certifications.stream().map(Certification::getRoutine).toList()) {
				String image = certifications.stream()
					.filter(c -> c.getRoutine().getId().equals(routine.getId()))
					.findFirst()
					.map(Certification::getImage)
					.orElse(BLANK);
				imageResponses.add(CertificationsMapper.toCertificateImageResponse(routine.getId(), image));
			}

			Inventory inventory = inventorySearchRepository.findDefault(member.getId(), ItemType.valueOf(roomType.name()));
			String awakeImage = inventory != null ? inventory.getItem().getAwakeImage() : BLANK;
			String sleepImage = inventory != null ? inventory.getItem().getSleepImage() : BLANK;

			responses.add(CertificationsMapper.toTodayCertificateRankResponse(
				i + 1, member, 0, awakeImage, sleepImage, 
				CertificationsMapper.toCertificateImagesResponse(imageResponses), false));
		}
		return responses;
	}
}
