    public void generateData(int totalJurors, boolean isCourtOwned) {
        stopWatch.start();

        jurorRepository.truncateTable();
        jurorPoolRepository.truncateTable();
        digitalResponseRepository.truncateTable();
        paperResponseRepository.truncateTable();
        poolRequestRepository.truncateTable();

        log.info("Generating data for {} jurors. Court owned: {}", totalJurors, isCourtOwned);

        List<PoolRequest> pools = generatePoolRequests(isCourtOwned);
        Util.batchSave(poolRequestRepository, pools, BATCH_SIZE);

        Map<JurorStatus, Integer> jurorStatusCountMap = distributeJurorsByStatus(totalJurors);
        List<JurorAccountDetailsDto> jurorAccountDetailsDtos = createJurorAccountDetailsDtos(isCourtOwned, jurorStatusCountMap);

        Util.batchSave(jurorRepository, 
            jurorAccountDetailsDtos.stream().map(JurorAccountDetailsDto::getJuror).toList(), 
            BATCH_SIZE);

        List<AbstractJurorResponse> responses = jurorAccountDetailsDtos.stream()
            .map(JurorAccountDetailsDto::getJurorResponse)
            .filter(Objects::nonNull)
            .toList();

        List<DigitalResponse> digitalResponses = responses.stream()
            .filter(r -> r instanceof DigitalResponse)
            .map(r -> (DigitalResponse) r)
            .toList();
        List<PaperResponse> paperResponses = responses.stream()
            .filter(r -> r instanceof PaperResponse)
            .map(r -> (PaperResponse) r)
            .toList();

        Util.batchSave(digitalResponseRepository, digitalResponses, BATCH_SIZE);
        Util.batchSave(paperResponseRepository, paperResponses, BATCH_SIZE);

        Util.batchSave(jurorPoolRepository,
            jurorAccountDetailsDtos.stream().map(JurorAccountDetailsDto::getJurorPools).flatMap(List::stream).toList(),
            BATCH_SIZE);
        stopWatch.stop();
    }

    private List<PoolRequest> generatePoolRequests(boolean isCourtOwned) {
        stopWatch.start("Generating Pool Requests");
        List<PoolRequestGenerator> generators = new ArrayList<>();
        for (PoolRequestGeneratorUtil.CourtType type : PoolRequestGeneratorUtil.CourtType.values()) {
            generators.add(PoolRequestGeneratorUtil.create(isCourtOwned, type));
        }

        List<PoolRequest> pools = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            PoolRequestGenerator generator = generators.get(RandomGenerator.nextInt(0, generators.size()));
            pools.add(generator.generate());
        }
        stopWatch.stop();
        return pools;
    }

    private Map<JurorStatus, Integer> distributeJurorsByStatus(int totalJurors) {
        Map<JurorStatus, Integer> distribution = new EnumMap<>(JurorStatus.class);
        int remaining = totalJurors;

        // Example distribution logic
        for (JurorStatus status : JurorStatus.values()) {
            int count = totalJurors / JurorStatus.values().length;
            distribution.put(status, count);
            remaining -= count;
        }
        distribution.put(JurorStatus.SUMMONED, distribution.get(JurorStatus.SUMMONED) + remaining);
        return distribution;
    }

