                String locname = item.getItemMeta().getLocalizedName();
                if (locname.equals("ru.cyanworld.cyanuniverse.coding.location")) {
                    event.setCancelled(true);
                    Location loc = event.getClickedBlock().getLocation();
                    World world = player.getWorld();
                    CodeEventHandler handler = codeMap.get(world);
                    if (handler != null) {
                        UUID eventid = UUID.randomUUID();
                        handler.runCode("СобытиеЛокация_Установка", eventid, player, loc);
                        player.sendMessage("§aМестоположение установлено!");
                        Utils.playCustomSound("ok", player);
                    }
                }
            }
        }
    }

