    @Override
    @Transactional(rollbackFor = Exception.class)
    public void updateShortLink(ShortLinkUpdateReqDTO requestParam) {
        ShortLinkDO shortLinkDO = baseMapper.selectOne(Wrappers.lambdaQuery(ShortLinkDO.class)
                .eq(ShortLinkDO::getFullShortUrl, requestParam.getFullShortUrl()));
        if (shortLinkDO == null) {
            throw new ClientException("短链接不存在");
        }
        if (StrUtil.isNotBlank(requestParam.getOriginUrl())) {
            shortLinkDO.setOriginUrl(requestParam.getOriginUrl());
            stringRedisTemplate.opsForValue().set(
                    String.format(GOTO_SHORT_LINK_KEY, requestParam.getFullShortUrl()),
                    requestParam.getOriginUrl(),
                    LinkUtil.getLinkCacheValidTime(requestParam.getValidDate()), TimeUnit.MILLISECONDS
            );
        }
        if (StrUtil.isNotBlank(requestParam.getGid())) {
            String originGid = shortLinkDO.getGid();
            if (!Objects.equals(originGid, requestParam.getGid())) {
                RLock lock = redissonClient.getLock(String.format(LOCK_GID_UPDATE_KEY, originGid));
                lock.lock();
                try {
                    shortLinkDO.setGid(requestParam.getGid());
                    ShortLinkGotoDO gotoDO = shortLinkGotoMapper.selectOne(Wrappers.lambdaQuery(ShortLinkGotoDO.class)
                            .eq(ShortLinkGotoDO::getFullShortUrl, requestParam.getFullShortUrl()));
                    if (gotoDO != null) {
                        gotoDO.setGid(requestParam.getGid());
                        shortLinkGotoMapper.updateById(gotoDO);
                    }
                } finally {
                    lock.unlock();
                }
            }
        }
        if (requestParam.getValidDateType() != null) {
            shortLinkDO.setValidDateType(requestParam.getValidDateType());
        }
        if (requestParam.getValidDate() != null) {
            shortLinkDO.setValidDate(requestParam.getValidDate());
        }
        if (StrUtil.isNotBlank(requestParam.getDescribe())) {
            shortLinkDO.setDescribe(requestParam.getDescribe());
        }
        baseMapper.updateById(shortLinkDO);
    }

