    @Override
    public void restoreUrl(String shortUri, ServletRequest request, ServletResponse response) {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;
        String fullShortUrl = StrBuilder.create(createShortLinkDefaultDomain).append("/").append(shortUri).toString();

        // 1. Try Cache
        String originUrl = stringRedisTemplate.opsForValue().get(String.format(GOTO_SHORT_LINK_KEY, fullShortUrl));
        if (StrUtil.isNotBlank(originUrl)) {
            httpResponse.sendRedirect(originUrl);
            return;
        }

        // 2. Try DB with Lock to prevent cache penetration
        RLock lock = redissonClient.getLock(String.format(LOCK_GOTO_SHORT_LINK_KEY, fullShortUrl));
        lock.lock();
        try {
            originUrl = stringRedisTemplate.opsForValue().get(String.format(GOTO_SHORT_LINK_KEY, fullShortUrl));
            if (StrUtil.isNotBlank(originUrl)) {
                httpResponse.sendRedirect(originUrl);
                return;
            }
            ShortLinkDO shortLinkDO = baseMapper.selectOne(Wrappers.lambdaQuery(ShortLinkDO.class)
                    .eq(ShortLinkDO::getFullShortUrl, fullShortUrl));
            if (shortLinkDO == null || shortLinkDO.getEnableStatus() != 0) {
                stringRedisTemplate.opsForValue().set(String.format(GOTO_IS_NULL_SHORT_LINK_KEY, fullShortUrl), "1", 5, TimeUnit.MINUTES);
                throw new ClientException("短链接不存在或已禁用");
            }
            originUrl = shortLinkDO.getOriginUrl();
            stringRedisTemplate.opsForValue().set(String.format(GOTO_SHORT_LINK_KEY, fullShortUrl), originUrl, 
                    LinkUtil.getLinkCacheValidTime(shortLinkDO.getValidDate()), TimeUnit.MILLISECONDS);
            httpResponse.sendRedirect(originUrl);
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void shortLinkStats(String fullShortUrl, String gid, ShortLinkStatsRecordDTO shortLinkStatsRecord) {
        delayShortLinkStatsProducer.send(shortLinkStatsRecord);
    }

    private String generateSuffix(ShortLinkCreateReqDTO requestParam) {
        return HashUtil.hashToBase62(requestParam.getOriginUrl() + UUID.fastUUID());
    }

    private void verificationWhitelist(String originUrl) {
        if (Boolean.TRUE.equals(gotoDomainWhiteListConfiguration.getEnable())) {
            String domain = LinkUtil.extractDomain(originUrl);
            if (!gotoDomainWhiteListConfiguration.getDetails().contains(domain)) {
                throw new ClientException("域名不在白名单中");
            }
        }
    }

    private String getFavicon(String originUrl) {
        return "https://www.google.com/s2/favicons?domain=" + LinkUtil.extractDomain(originUrl);
    }
